//! Robustness tests over *real-world* PDF fixtures.
//!
//! `container::make_sample_pdf` is a toy: a single classic cross-reference
//! *table* with only inline (uncompressed) objects. Modern producers (Acrobat,
//! qpdf, most libraries) instead emit cross-reference **streams** and **object
//! streams**, and existing AcroForms often store `/Fields` as an *indirect
//! reference* rather than a direct array.
//!
//! The fixtures here (`tests/fixtures/real_plain.pdf`,
//! `tests/fixtures/real_acroform.pdf`) exercise exactly those shapes. They are
//! regenerated by `tests/fixtures/generate_fixtures.py` (pikepdf/qpdf) and
//! committed so the suite needs no Python at test time.

mod common;

use common::{consumer_policy, field, mint, signer_request, trust, AUDIENCE, ISSUER};
use lopdf::{Document, Object};
use signpdf_core::crypto::{sha256_hex, KeyPair};
use signpdf_core::oidc::compute_nonce;
use signpdf_core::workflow::{PrepareRequest, SignerSpec};
use signpdf_core::{
    pades_sign, pades_verify, prepare, sign, verify, Field, FieldType, Policy, Rect,
    SignAppearance, SignerStatus, SigningOrder,
};

/// A modern PDF: one page, cross-reference stream + object streams, no AcroForm.
const REAL_PLAIN: &[u8] = include_bytes!("fixtures/real_plain.pdf");
/// A modern PDF whose pre-existing AcroForm stores `/Fields` as an indirect
/// reference to an array holding a single text field (`existing_name`).
const REAL_ACROFORM: &[u8] = include_bytes!("fixtures/real_acroform.pdf");

fn appearance(name: &str) -> SignAppearance {
    SignAppearance {
        name: name.to_string(),
        reason: Some("real-world e2e".into()),
        location: None,
        page_index: 0,
        rect: Some([72.0, 700.0, 300.0, 740.0]),
        caption: None,
        ink: None,
    }
}

fn resolve<'a>(doc: &'a Document, obj: &'a Object) -> Option<&'a Object> {
    match obj {
        Object::Reference(r) => doc.get_object(*r).ok(),
        other => Some(other),
    }
}

/// Re-parse a PDF and return the `/T` names of every terminal AcroForm field,
/// resolving indirect references throughout (catalog → AcroForm → /Fields).
fn acroform_field_names(pdf: &[u8]) -> Vec<String> {
    let doc = Document::load_mem(pdf).expect("re-parse PDF");
    let root_id = doc
        .trailer
        .get(b"Root")
        .and_then(|o| o.as_reference())
        .expect("trailer /Root");
    let catalog = doc
        .get_object(root_id)
        .and_then(|o| o.as_dict())
        .expect("catalog dict");
    let acroform = match catalog.get(b"AcroForm") {
        Ok(o) => resolve(&doc, o)
            .and_then(|o| o.as_dict().ok())
            .expect("AcroForm dict"),
        Err(_) => return Vec::new(),
    };
    let fields = acroform
        .get(b"Fields")
        .ok()
        .and_then(|o| resolve(&doc, o))
        .and_then(|o| o.as_array().ok())
        .cloned()
        .unwrap_or_default();
    fields
        .iter()
        .filter_map(|f| resolve(&doc, f).and_then(|o| o.as_dict().ok()))
        .filter_map(|d| d.get(b"T").ok().and_then(|t| t.as_str().ok()))
        .map(|s| String::from_utf8_lossy(s).into_owned())
        .collect()
}

#[test]
fn real_world_plain_pdf_signs_and_verifies() {
    let alice = KeyPair::generate();
    let signed = pades_sign(REAL_PLAIN, &alice, &appearance("Alice"), None).unwrap();

    // True incremental update: the original xref-stream/object-stream bytes are
    // preserved verbatim as the prefix.
    assert!(signed.starts_with(b"%PDF-"));
    assert_eq!(&signed[..REAL_PLAIN.len()], REAL_PLAIN);

    let results = pades_verify(&signed).unwrap();
    assert_eq!(results.len(), 1);
    assert!(results[0].is_valid());
    assert!(results[0].covers_to_eof, "single signature covers the file");
}

#[test]
fn real_world_acroform_pdf_preserves_existing_fields() {
    // Sanity: the fixture really does carry one pre-existing (non-signature) field.
    assert_eq!(acroform_field_names(REAL_ACROFORM), vec!["existing_name"]);

    let alice = KeyPair::generate();
    let signed = pades_sign(REAL_ACROFORM, &alice, &appearance("Alice"), None).unwrap();

    let results = pades_verify(&signed).unwrap();
    assert_eq!(results.len(), 1);
    assert!(results[0].is_valid());

    // Regression guard: when /Fields is an indirect reference we must NOT drop
    // the pre-existing field while adding the signature field.
    let names = acroform_field_names(&signed);
    assert!(
        names.iter().any(|n| n == "existing_name"),
        "pre-existing form field must survive signing, got {names:?}"
    );
    assert_eq!(
        names.len(),
        2,
        "existing field + new signature field, got {names:?}"
    );
}

#[test]
fn real_world_acroform_pdf_supports_stacked_signatures() {
    let alice = KeyPair::generate();
    let bob = KeyPair::generate();

    let after_alice = pades_sign(REAL_ACROFORM, &alice, &appearance("Alice"), None).unwrap();
    let after_bob = pades_sign(&after_alice, &bob, &appearance("Bob"), None).unwrap();

    // Alice's signed bytes remain unchanged inside the twice-signed file.
    assert_eq!(&after_bob[..after_alice.len()], &after_alice[..]);

    let results = pades_verify(&after_bob).unwrap();
    assert_eq!(results.len(), 2, "both signatures present");
    assert!(results.iter().all(|r| r.is_valid()));

    let names = acroform_field_names(&after_bob);
    assert!(
        names.iter().any(|n| n == "existing_name"),
        "pre-existing field must survive both increments, got {names:?}"
    );
    assert_eq!(
        names.len(),
        3,
        "existing field + two signature fields, got {names:?}"
    );
}

fn two_signer_request(pdf: &[u8]) -> (KeyPair, PrepareRequest) {
    let key = KeyPair::generate();
    let (id_token, idp_jwk) = mint(
        "preparer@example.com",
        &compute_nonce(&key.public_sec1(), &sha256_hex(pdf)),
    );
    let req = PrepareRequest {
        title: "Real-world NDA".to_string(),
        signers: vec![
            SignerSpec {
                id: "s1".into(),
                name: "Alice".into(),
                handle: "alice@example.com".into(),
                role: "Disclosing Party".into(),
                order: 1,
                identity_policy: consumer_policy("alice@example.com"),
            },
            SignerSpec {
                id: "s2".into(),
                name: "Bob".into(),
                handle: "bob@example.com".into(),
                role: "Receiving Party".into(),
                order: 2,
                identity_policy: consumer_policy("bob@example.com"),
            },
        ],
        fields: vec![
            Field {
                id: "f1".into(),
                field_type: FieldType::Signature,
                page: 0,
                rect: Rect {
                    x: 72.0,
                    y: 120.0,
                    w: 200.0,
                    h: 48.0,
                },
                assigned_signer: "s1".into(),
                required: true,
                value: None,
                label: None,
                group: None,
                options: None,
                date_format: None,
                signing_date: false,
                number_format: None,
                value_format: None,
                length: None,
                check_message: None,
                formula: None,
            },
            Field {
                id: "f2".into(),
                field_type: FieldType::Signature,
                page: 0,
                rect: Rect {
                    x: 300.0,
                    y: 120.0,
                    w: 200.0,
                    h: 48.0,
                },
                assigned_signer: "s2".into(),
                required: true,
                value: None,
                label: None,
                group: None,
                options: None,
                date_format: None,
                signing_date: false,
                number_format: None,
                value_format: None,
                length: None,
                check_message: None,
                formula: None,
            },
        ],
        policy: Policy {
            signing_order: SigningOrder::Sequential,
            allowed_signature_types: vec!["PAdES".into()],
            expiry: None,
            ..Default::default()
        },
        id_token,
        idp_jwk,
        audience: AUDIENCE.to_string(),
        allowed_issuers: vec![ISSUER.to_string()],
        service_link: None,
        documents: Vec::new(),
        verify_at: None,
    };
    (key, req)
}

#[test]
fn real_world_acroform_workflow_two_signer_flow_verifies() {
    // The whole envelope workflow must run over a real-world PDF input, not just
    // the toy sample.
    let (preparer_key, req) = two_signer_request(REAL_ACROFORM);
    let prepared = prepare(REAL_ACROFORM, &req, &preparer_key).unwrap();

    let (alice_key, alice_req) = signer_request("alice@example.com", &prepared, "s1");
    let after_alice = sign(&prepared, &alice_key, &alice_req).unwrap();

    let (bob_key, bob_req) = signer_request("bob@example.com", &after_alice, "s2");
    let after_bob = sign(&after_alice, &bob_key, &bob_req).unwrap();

    let report = verify(&after_bob, &trust()).unwrap();
    assert!(
        report.valid,
        "report should be valid: {:?}",
        report.messages
    );
    assert!(report.complete);
    assert!(report.audit_ok);
    assert!(report.order_ok);
    assert_eq!(report.signatures.len(), 2);
    assert!(report.signatures.iter().all(|s| s.valid));

    let env = report.envelope.unwrap();
    assert!(env.signers.iter().all(|s| s.status == SignerStatus::Signed));

    // The user's pre-existing form field is still present after the full flow.
    let names = acroform_field_names(&after_bob);
    assert!(
        names.iter().any(|n| n == "existing_name"),
        "pre-existing field must survive the workflow, got {names:?}"
    );
}

/// Field values drawn into a revision of a modern (xref-stream / object-stream) PDF still pass
/// the revision audit, and the pre-existing form field survives untouched.
#[test]
fn real_world_plain_pdf_workflow_with_field_values_verifies() {
    let (preparer_key, mut req) = two_signer_request(REAL_PLAIN);
    req.fields
        .push(field("company", "s1", FieldType::Text, 0, 400.0));
    let prepared = prepare(REAL_PLAIN, &req, &preparer_key).unwrap();
    let (k, mut r) = signer_request("alice@example.com", &prepared, "s1");
    r.field_values = vec![("company".into(), "Contoso Ltd".into())];
    let signed = sign(&prepared, &k, &r).unwrap();
    let report = verify(&signed, &trust()).unwrap();
    assert!(report.valid, "{:?}", report.messages);
}
